WITH metrics AS (SELECT id, customer_id, plan, start_date, end_date, monthly_fee, status, LEAD(monthly_fee, 1) OVER (PARTITION BY status ORDER BY monthly_fee, id) AS next_monthly_fee, DENSE_RANK() OVER (PARTITION BY plan, status ORDER BY monthly_fee DESC NULLS FIRST) AS monthly_fee_dense_rank FROM subscriptions) SELECT id, start_date, end_date, status, next_monthly_fee, monthly_fee_dense_rank FROM metrics ORDER BY status DESC
